from pathlib import Path
p = Path('problems/23/writeup/_codex_eq_cert2_chart_lp.py')
s = p.read_text(encoding='utf-8')
s = s.replace('def maxcut_facet_exprs(mode: str) -> list[tuple[str, sp.Expr]]:', 'def maxcut_facet_exprs(mode: str, selected_masks=()) -> list[tuple[str, sp.Expr]]:')
s = s.replace('    if mode not in {"tight", "all"}:\n        raise ValueError(f"unknown maxcut facet mode {mode!r}")', '    if mode not in {"tight", "all", "selected"}:\n        raise ValueError(f"unknown maxcut facet mode {mode!r}")\n    selected_masks = {int(m) for m in selected_masks}')
s = s.replace('        if mode == "tight" and qmax_value(c, ones) != 0:\n            continue', '        if mode == "tight" and qmax_value(c, ones) != 0:\n            continue\n        if mode == "selected" and mask not in selected_masks:\n            continue')
s = s.replace('def build_chart(chart: int, extra_maxcut: str = "none")', 'def build_chart(chart: int, extra_maxcut: str = "none", maxcut_masks=())')
s = s.replace('    raw_generators.extend(maxcut_facet_exprs(extra_maxcut))', '    raw_generators.extend(maxcut_facet_exprs(extra_maxcut, maxcut_masks))')
s = s.replace('        "extra_maxcut": extra_maxcut,\n', '        "extra_maxcut": extra_maxcut,\n        "maxcut_masks": [int(m) for m in maxcut_masks],\n')
s = s.replace('    extra_maxcut: str,\n    max_columns_per_generator', '    extra_maxcut: str,\n    maxcut_masks: list[int],\n    max_columns_per_generator')
s = s.replace('    target_hat, generators, meta = build_chart(chart, extra_maxcut=extra_maxcut)', '    target_hat, generators, meta = build_chart(chart, extra_maxcut=extra_maxcut, maxcut_masks=maxcut_masks)')
s = s.replace('    ap.add_argument("--extra-maxcut", choices=["none", "tight", "all"], default="none")', '    ap.add_argument("--extra-maxcut", choices=["none", "tight", "all", "selected"], default="none")\n    ap.add_argument("--maxcut-masks", default="")')
s = s.replace('        extra_maxcut=args.extra_maxcut,\n        max_columns_per_generator', '        extra_maxcut=args.extra_maxcut,\n        maxcut_masks=parse_ints(args.maxcut_masks) if args.maxcut_masks else [],\n        max_columns_per_generator')
p.write_text(s, encoding='utf-8')

p = Path('problems/23/writeup/_codex_eq_cert2_chart_rowgen.py')
s = p.read_text(encoding='utf-8')
s = s.replace('    target, generators, meta = base.build_chart(args.chart, extra_maxcut=args.extra_maxcut)', '    target, generators, meta = base.build_chart(args.chart, extra_maxcut=args.extra_maxcut, maxcut_masks=parse_ints(args.maxcut_masks) if args.maxcut_masks else [])')
s = s.replace('    ap.add_argument("--extra-maxcut", choices=["none", "tight", "all"], default="none")', '    ap.add_argument("--extra-maxcut", choices=["none", "tight", "all", "selected"], default="none")\n    ap.add_argument("--maxcut-masks", default="")')
s = s.replace('        "extra_maxcut": args.extra_maxcut,\n', '        "extra_maxcut": args.extra_maxcut,\n        "maxcut_masks": parse_ints(args.maxcut_masks) if args.maxcut_masks else [],\n')
p.write_text(s, encoding='utf-8')
